s=rcb_dtb.Session();m=s.model;d=s.data;j=m.joint('object_free_joint').qposadr[0]
def evalp(g,x):
 p=np.array(g[:3])+x[:3];r=R.from_rotvec(x[3:])*R.from_quat(g[3:]);q=r.as_quat();d.qpos[j:j+7]=np.r_[p, np.roll(q,1)];mujoco.mj_forward(m,d)
 cs=[]
 for c in d.contact[:d.ncon]:
  a=m.geom(c.geom1).name;b=m.geom(c.geom2).name
  if ('object_object' in a and ('bowl' in b or 'plate' in b)) or ('object_object' in b and ('bowl' in a or 'plate' in a)):cs.append(c.dist)
 return (min(cs) if cs else .02, rcb_dtb.keypoint_distance(p,np.roll(q,1),g))
rng=np.random.default_rng(41)
for k in range(8,16):
 g=np.array(s.goals[k]);best=(-1,None,None)
 for n in range(5):
  if n==0:x=np.zeros(6)
  else:x=rng.normal(size=6)*np.array([.003,.003,.003,.035,.035,.035])
  obj=lambda x: -evalp(g,x)[0]+100*max(0,evalp(g,x)[1]-.0145)**2
  rr=minimize(obj,x,method='Nelder-Mead',options={'maxiter':500,'xatol':1e-5,'fatol':1e-5})
  c,e=evalp(g,rr.x)
