import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation as R
from scipy.optimize import differential_evolution
sys.path.insert(0,'/opt/tools');import rcb_dtb
s=rcb_dtb.Session();m=s.model;d=s.data;j=m.joint('object_free_joint').qposadr[0]
def met(g,x):
 p=np.array(g[:3])+x[:3];r=R.from_rotvec(x[3:])*R.from_quat(g[3:]);q=np.roll(r.as_quat(),1);d.qpos[j:j+7]=np.r_[p,q];mujoco.mj_forward(m,d)
 cs=[]
 for c in d.contact[:d.ncon]:
  a=m.geom(c.geom1).name;b=m.geom(c.geom2).name
  if ('object_object' in a and ('bowl' in b or 'plate' in b)) or ('object_object' in b and ('bowl' in a or 'plate' in a)):cs.append(c.dist)
 return (min(cs) if cs else .02,rcb_dtb.keypoint_distance(p,q,g))
for k in [9,10,11,12,13,14]:
 g=np.array(s.goals[k]);bounds=[(-.015,.015)]*3+[(-.15,.15)]*3
 def obj(x):
  clear,dist=met(g,x)
  return -clear+20*max(0,dist-.0149)
 res=differential_evolution(obj,bounds,maxiter=90,popsize=12,polish=False,seed=42,workers=1)
 print(k,'goal',met(g,np.zeros(6)),'best',res.x,met(g,res.x),flush=True)
